import React from "react";
import { useNavigate } from "react-router-dom";

function DoctorCard({ doctor }) {
  const navigate = useNavigate();

  return (
    <div
      style={styles.card}
      onMouseEnter={(e) =>
        (e.currentTarget.style.transform = "translateY(-5px)")
      }
      onMouseLeave={(e) =>
        (e.currentTarget.style.transform = "translateY(0)")
      }
    >
      <img
        src={doctor.imageUrl || "https://randomuser.me/api/portraits/men/1.jpg"}
        alt="doctor"
        style={styles.image}
        onError={(e) => {
          e.target.src = "https://randomuser.me/api/portraits/men/1.jpg";
        }}
      />

      <h3 style={styles.name}>{doctor.name}</h3>
      <p style={styles.specialization}>
        {doctor.specialization}
      </p>

      <p style={styles.rating}>
        ⭐ {doctor.experience} yrs exp
      </p>

      <button
        style={styles.button}
        onClick={(e) => {
          e.stopPropagation();  // ✅ IMPORTANT
          navigate(`/book/${doctor.id}`)}
        }
      >
        Book Appointment
      </button>
    </div>
  );
}

const styles = {
  card: {
    width: "100%",
    height: "260px",   // makes it square-ish
    background: "#fff",
    borderRadius: "12px",
    boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
    padding: "15px",
    textAlign: "center",
    transition: "0.3s",
    cursor: "pointer",
  },
  image: {
    width: "80px",
    height: "80px",
    borderRadius: "50%",
    objectFit: "cover",
    marginBottom: "10px",
  },
  name: {
    margin: "5px 0",
    color: "#1976d2",
  },
  specialization: {
    fontSize: "14px",
    color: "#555",
  },
  rating: {
    fontSize: "14px",
    color: "#888",
    margin: "5px 0",
  },
  button: {
    marginTop: "10px",
    padding: "6px 12px",
    background: "#1976d2",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
  },
};

export default DoctorCard;
